function buildTranslationReverse(){
  const rev={};
  for(const [lng,map] of Object.entries(UI_TRANSLATIONS)){
    for(const [en,val] of Object.entries(map||{})){
      if(val && !rev[val]) rev[val]=en;
    }
  }
  return rev;
}
let TRANSLATION_REVERSE=null;
function canonicalEnglish(s){
  const key=String(s??'').trim();
  if(!TRANSLATION_REVERSE) TRANSLATION_REVERSE=buildTranslationReverse();
  return TRANSLATION_REVERSE[key] || key;
}
function tr(s){
  if(!s)return s;
  const key=canonicalEnglish(s);
  return activeLang==='en' ? key : ((UI_TRANSLATIONS[activeLang]||{})[key] || key);
}
function translateNodeTree(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  for(const n of nodes){
    if(n.parentElement?.closest('.languageIsolated'))continue;
    const current=String(n.nodeValue||'');
    const trimmed=current.trim();
    if(!trimmed)continue;
    const canonical=n.__tutCanonical || canonicalEnglish(trimmed);
    n.__tutCanonical=canonical;
    const translated=tr(canonical);
    const lead=current.match(/^\s*/)?.[0]||'';
    const tail=current.match(/\s*$/)?.[0]||'';
    n.nodeValue=lead+translated+tail;
  }
  root.querySelectorAll?.('input[placeholder],textarea[placeholder]').forEach(el=>{
    const current=el.getAttribute('placeholder')||'';
    if(!el.dataset.tutCanonicalPlaceholder)el.dataset.tutCanonicalPlaceholder=canonicalEnglish(current);
    el.setAttribute('placeholder',tr(el.dataset.tutCanonicalPlaceholder));
  });
  root.querySelectorAll?.('[title]').forEach(el=>{
    const current=el.getAttribute('title')||'';
    if(!el.dataset.tutCanonicalTitle)el.dataset.tutCanonicalTitle=canonicalEnglish(current);
    el.setAttribute('title',tr(el.dataset.tutCanonicalTitle));
  });
}
function refreshLanguage(){
  document.documentElement.lang=activeLang;
  document.documentElement.dir=activeLang==='ar'?'rtl':'ltr';
  translateNodeTree(document.body);
  const sel=document.getElementById('lang'); if(sel) sel.value=activeLang;
}


