function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
async function api(p,o={}){const token=localStorage.getItem('tut_session')||'';o.credentials='same-origin';o.headers={'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(o.headers||{})};const r=await fetch(p,o);const j=await r.json().catch(()=>({}));if(r.status===401&&p==='/api/me'){localStorage.removeItem('tut_session')}if(!r.ok)throw new Error(j.error||'Request failed');return j}
function go(id){if(id==='adminPane'&&(!me||me.role!=='owner'))id='home';document.querySelectorAll('.pane').forEach(x=>x.classList.add('hidden'));$(id).classList.remove('hidden');if(id==='post')scheduleMapRefresh();if(id==='market')loadMarket();if(id==='matches')loadMatches();if(id==='offers'){loadOffers();loadBookings()}if(id==='adminPane')loadAdmin();if(id==='verify')loadVerification();scrollTo({top:0,behavior:'smooth'})}

let TUT_TRANSLATION_OBSERVER=null;
let TUT_TRANSLATING=false;
function translateElementDeep(node){
  if(activeLang==='en' || TUT_TRANSLATING || !node)return;
  TUT_TRANSLATING=true;
  try{
    if(node.nodeType===Node.TEXT_NODE){
      const t=node.nodeValue?.trim();
      if(t){
        const c=node.__tutCanonical||canonicalEnglish(t);
        node.__tutCanonical=c;
        const x=tr(c);
        if(x!==t){
          const lead=node.nodeValue.match(/^\s*/)?.[0]||'';
          const tail=node.nodeValue.match(/\s*$/)?.[0]||'';
          node.nodeValue=lead+x+tail;
        }
      }
    }else if(node.nodeType===Node.ELEMENT_NODE){
      translateNodeTree(node);
    }
  }finally{TUT_TRANSLATING=false}
}
function startTranslationObserver(){
  if(TUT_TRANSLATION_OBSERVER)TUT_TRANSLATION_OBSERVER.disconnect();
  TUT_TRANSLATION_OBSERVER=new MutationObserver(mutations=>{
    if(activeLang==='en'||TUT_TRANSLATING)return;
    for(const mu of mutations){
      if(mu.type==='childList'){
        mu.addedNodes.forEach(translateElementDeep);
      }else if(mu.type==='attributes'){
        translateElementDeep(mu.target);
      }
    }
  });
  TUT_TRANSLATION_OBSERVER.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['placeholder','title']});
}
function setLanguage(lang){
  activeLang=lang;
  localStorage.setItem('tut_lang',lang);
  startTranslationObserver();
  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  TRANSLATION_REVERSE=buildTranslationReverse();

  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const k=el.dataset.i18n;
    const en=(T.en&&T.en[k])||el.dataset.tutCanonical||canonicalEnglish(el.textContent.trim());
    el.dataset.tutCanonical=en;
    el.textContent=(T[lang]&&T[lang][k]) || tr(en);
  });

  // Recreate dynamic forms using the newly selected language.
  if(document.getElementById('fields')&&document.getElementById('resource')){
    try{renderFields()}catch{}
  }
  try{renderAccount()}catch{}
  try{renderAuth()}catch{}
  if(document.getElementById('marketList') && listings?.length){try{loadMarket()}catch{}}
  if(document.getElementById('bookingList') && me){try{loadBookings()}catch{}}
  refreshLanguage();
  document.querySelectorAll('option').forEach(o=>{const c=o.dataset.tutCanonical||canonicalEnglish(o.textContent);o.dataset.tutCanonical=c;o.textContent=tr(c)});
  requestAnimationFrame(()=>{translateNodeTree(document.body);setTimeout(()=>translateNodeTree(document.body),80);});
  renderNeedChooser();
  setTimeout(applyStrictSiteLanguage,0);
}

