async function loadVerification(){
  if(!me){if($('verificationStatus'))$('verificationStatus').textContent=tr('Sign in to submit verification.');return}
  try{
    const j=await api('/api/verification/me'),v=j.verification||{};
    $('verificationStatus').textContent=tr('Verification status')+': '+tr(v.status||'not_submitted');
    if(v.role)$('verifyRole').value=v.role;if(v.legalName)$('verifyLegalName').value=v.legalName;if(v.country)$('verifyCountry').value=v.country;if(v.identityNumber)$('verifyIdentityNumber').value=v.identityNumber;
    if(v.licenceNumber)$('verifyLicence').value=v.licenceNumber;if(v.licenceExpiry)$('verifyLicenceExpiry').value=v.licenceExpiry;if(v.endorsements)$('verifyEndorsements').value=v.endorsements;if(v.vehicleId)$('verifyVehicle').value=v.vehicleId;if(v.registrationNumber){if($('verifyRegistration'))$('verifyRegistration').value=v.registrationNumber;if($('verifyBusinessRegistration'))$('verifyBusinessRegistration').value=v.registrationNumber}if(v.notes)$('verifyNotes').value=v.notes;renderVerifyLicenceClasses();(v.licenceClasses||[]).forEach(val=>{const cb=[...document.querySelectorAll('#verifyLicenceClasses input')].find(x=>x.value===val);if(cb)cb.checked=true});updateVerificationRoleFields();
    if(me.role==='owner')loadOwnerVerifications();
  }catch(e){}
}
async function submitVerificationV1(e){
  e.preventDefault();if(!me){alert(tr('Sign in to submit verification.'));return}
  try{
    const role=$('verifyRole').value;
    const [identityFile,selfieFile,licenceFile]=await Promise.all([verifyFileData('verifyIdentityFile'),verifyFileData('verifySelfieFile'),verifyFileData('verifyLicenceFile')]);
    const licenceClasses=[...document.querySelectorAll('#verifyLicenceClasses input:checked')].map(x=>x.value);
    if((role==='driver'||role==='carrier')&&!licenceClasses.length){$('verifySubmitMsg').textContent=tr('Choose at least one licence class.');return}
    const registration=$('verifyRegistration')?.value||$('verifyBusinessRegistration')?.value||'';
    const body={role,legalName:$('verifyLegalName').value,country:$('verifyCountry').value,identityNumber:$('verifyIdentityNumber').value,licenceNumber:$('verifyLicence')?.value||'',licenceClasses,licenceExpiry:$('verifyLicenceExpiry')?.value||'',endorsements:$('verifyEndorsements')?.value||'',registrationNumber:registration,vehicleId:$('verifyVehicle')?.value||'',notes:$('verifyNotes').value,files:{identity:identityFile,selfie:selfieFile,license:licenceFile}};
    const j=await api('/api/verification/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    $('verifySubmitMsg').textContent=tr(j.message||'Verification submitted for review.');loadVerification();
  }catch(e){$('verifySubmitMsg').textContent=tr(e.message)}
}
async function loadOwnerVerifications(){
  if(!me||me.role!=='owner'||!$('ownerVerificationQueue'))return;
  const j=await api('/api/admin/verifications');
  $('ownerVerificationQueue').innerHTML=j.items.length?'<h3>'+tr('Owner review queue')+'</h3>'+j.items.map(x=>`<div class="verifyReview"><div><strong>${esc(x.name||x.email)}</strong><small>${esc(x.email)} · ${tr(x.verification.status||'pending')}</small></div><div><button class="outlineBtn mini" onclick="reviewVerification('${x.userId}','verified')">${tr('Approve')}</button><button class="outlineBtn mini" onclick="reviewVerification('${x.userId}','rejected')">${tr('Reject')}</button></div></div>`).join(''):'';
}
async function reviewVerification(id,status){await api(`/api/admin/verifications/${id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status})});loadOwnerVerifications()}
document.getElementById('verificationForm')?.addEventListener('submit',submitVerificationV1);
setTimeout(()=>{try{loadVerification()}catch{}},300);


