function verifyFileData(id){
  return new Promise((resolve,reject)=>{const f=$(id)?.files?.[0];if(!f)return resolve('');if(f.size>3*1024*1024)return reject(new Error(tr('Each file must be 3MB or less.')));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error(tr('Could not read file.')));r.readAsDataURL(f);});
}
function renderVerifyLicenceClasses(){
  const host=$('verifyLicenceClasses'); if(!host)return;
  const m=detectedMarket.profile?detectedMarket:detectLocalMarket();
  const licences=(m.profile?.licences||[]).map(x=>x[0]);
  host.innerHTML=`<fieldset class="specChecks verifyLicenceChoices"><legend>${tr('Licence class')}</legend>${licences.map(x=>`<label class="checkCard"><input type="checkbox" value="${esc(x)}"><span class="checkBoxVisual">✓</span><span>${esc(x)}</span></label>`).join('')}</fieldset>`;
}
function updateVerificationRoleFields(){
  const role=document.getElementById('verifyRole')?.value||'';
  document.querySelectorAll('[data-role-field]').forEach(el=>{
    const roles=(el.getAttribute('data-role-field')||'').split(/\s+/);
    el.style.display=roles.includes(role)?'block':'none';
  });
}
